-- 0210_mdm_server_generated_skus
-- B09q (owner, 2026-11-17; ADR-0072): a product's SKU is generated by the server at creation, a short prefix from the
-- product's category and a zero-padded number (EGG-0001), unique, never reused and never edited.
-- * `mdm.category.sku_prefix`: two to five capital letters. A category created without one (an earlier API version,
--   a fixture) takes the first three letters of its code, or CAT when its code has fewer than two; existing categories
--   are backfilled the same way. Changing the prefix later changes only the SKUs of products made after it.
-- * `mdm.sku_counter`: one counter per prefix, written only by `mdm.allocate_sku` (SECURITY DEFINER, owned by
--   hk_owner). Its value only moves forward: lowering, deleting or truncating it is refused for every role (HK004
--   `ck_sku_counter_forward`), so a number is never handed out twice.
-- * `mdm.allocate_sku(prefix)`: the prefix's next number, stepping over any SKU a product already holds (a SKU typed
--   before this migration), formatted `<PREFIX>-<number>`, zero-padded to four digits and never truncated.
-- * A SKU is unique over every product ever made, live or archived (`uq_product_sku` replaces the live-only index),
--   and never changes (HK004 `ck_product_sku_fixed`, every role).
-- Data category: PUBLIC (catalogue codes); no personal data.
-- Rollback: tested (`pnpm db:rollback`): the live-only index returns; SKUs already generated stay as they are.

-- migrate:up
ALTER TABLE mdm.category ADD COLUMN sku_prefix text NULL CONSTRAINT ck_category_sku_prefix CHECK (sku_prefix ~ '^[A-Z]{2,5}$');

CREATE FUNCTION mdm.category_sku_prefix_default() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog
AS $$
DECLARE
  letters text;
BEGIN
  IF NEW.sku_prefix IS NULL THEN
    letters := regexp_replace(upper(NEW.code), '[^A-Z]', '', 'g');
    NEW.sku_prefix := CASE WHEN length(letters) >= 2 THEN left(letters, 3) ELSE 'CAT' END;
  END IF;
  RETURN NEW;
END
$$;
REVOKE ALL ON FUNCTION mdm.category_sku_prefix_default() FROM PUBLIC;
CREATE TRIGGER trg_category_sku_prefix BEFORE INSERT OR UPDATE OF sku_prefix ON mdm.category
  FOR EACH ROW EXECUTE FUNCTION mdm.category_sku_prefix_default();

-- The backfill is a schema change, not an edit of the category: it leaves `version` where it was, so a client holding
-- the category's version can still change it.
ALTER TABLE mdm.category DISABLE TRIGGER trg_category_version;
UPDATE mdm.category
   SET sku_prefix = CASE WHEN length(regexp_replace(upper(code), '[^A-Z]', '', 'g')) >= 2
                         THEN left(regexp_replace(upper(code), '[^A-Z]', '', 'g'), 3) ELSE 'CAT' END
 WHERE sku_prefix IS NULL;
ALTER TABLE mdm.category ENABLE TRIGGER trg_category_version;
ALTER TABLE mdm.category ALTER COLUMN sku_prefix SET NOT NULL;

CREATE TABLE mdm.sku_counter (
  prefix     text PRIMARY KEY CONSTRAINT ck_sku_counter_prefix CHECK (prefix ~ '^[A-Z]{2,5}$'),
  last_value bigint NOT NULL CONSTRAINT ck_sku_counter_value CHECK (last_value > 0),
  updated_at timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE mdm.sku_counter IS 'class=PROJECTION';

CREATE FUNCTION mdm.sku_counter_forward() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog
AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.prefix = OLD.prefix AND NEW.last_value > OLD.last_value THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'mdm.sku_counter only moves forward: a SKU number is never handed out twice'
    USING ERRCODE = 'HK004', CONSTRAINT = 'ck_sku_counter_forward';
END
$$;
REVOKE ALL ON FUNCTION mdm.sku_counter_forward() FROM PUBLIC;
CREATE TRIGGER trg_sku_counter_forward BEFORE UPDATE OR DELETE ON mdm.sku_counter
  FOR EACH ROW EXECUTE FUNCTION mdm.sku_counter_forward();
CREATE TRIGGER trg_sku_counter_no_truncate BEFORE TRUNCATE ON mdm.sku_counter
  FOR EACH STATEMENT EXECUTE FUNCTION mdm.sku_counter_forward();

-- The next SKU of a prefix. The upsert locks the counter row for the rest of the caller's transaction, so concurrent
-- creators of one prefix queue behind each other; a number a product already holds is skipped, never reused.
CREATE FUNCTION mdm.allocate_sku(p_prefix text) RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = pg_catalog
AS $$
DECLARE
  issued bigint;
  candidate text;
BEGIN
  LOOP
    INSERT INTO mdm.sku_counter AS c (prefix, last_value) VALUES (p_prefix, 1)
    ON CONFLICT (prefix) DO UPDATE SET last_value = c.last_value + 1, updated_at = now()
    RETURNING c.last_value INTO issued;
    candidate := p_prefix || '-' || CASE WHEN length(issued::text) >= 4 THEN issued::text ELSE lpad(issued::text, 4, '0') END;
    IF NOT EXISTS (SELECT 1 FROM mdm.product p WHERE p.sku = candidate) THEN
      RETURN candidate;
    END IF;
  END LOOP;
END
$$;
REVOKE ALL ON FUNCTION mdm.allocate_sku(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mdm.allocate_sku(text) TO hk_app, hk_worker;

REVOKE ALL ON mdm.sku_counter FROM PUBLIC;
GRANT SELECT ON mdm.sku_counter TO hk_app, hk_worker;

-- Never reused: unique over live and archived products alike.
DROP INDEX mdm.uq_product_sku;
CREATE UNIQUE INDEX uq_product_sku ON mdm.product (sku);

CREATE FUNCTION mdm.product_sku_fixed() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog
AS $$
BEGIN
  RAISE EXCEPTION 'product %: a SKU never changes', OLD.id USING ERRCODE = 'HK004', CONSTRAINT = 'ck_product_sku_fixed';
END
$$;
REVOKE ALL ON FUNCTION mdm.product_sku_fixed() FROM PUBLIC;
CREATE TRIGGER trg_product_sku_fixed BEFORE UPDATE OF sku ON mdm.product
  FOR EACH ROW WHEN (OLD.sku IS DISTINCT FROM NEW.sku) EXECUTE FUNCTION mdm.product_sku_fixed();

-- migrate:down
DROP TRIGGER trg_product_sku_fixed ON mdm.product;
DROP FUNCTION mdm.product_sku_fixed();
DROP INDEX mdm.uq_product_sku;
CREATE UNIQUE INDEX uq_product_sku ON mdm.product (sku) WHERE deleted_at IS NULL;
DROP FUNCTION mdm.allocate_sku(text);
DROP TRIGGER trg_sku_counter_no_truncate ON mdm.sku_counter;
DROP TRIGGER trg_sku_counter_forward ON mdm.sku_counter;
DROP TABLE mdm.sku_counter;
DROP FUNCTION mdm.sku_counter_forward();
DROP TRIGGER trg_category_sku_prefix ON mdm.category;
DROP FUNCTION mdm.category_sku_prefix_default();
ALTER TABLE mdm.category DROP COLUMN sku_prefix;
